template:
PREFIX s: <https://schema.org/>
PREFIX seed: <https://seeds.local/ontology/>
SELECT ?item ?id ?title ?priority ?rank ?status ?owner ?revision ?modified WHERE {
 GRAPH <https://seeds.local/project/aegis> {
  ?item seed:priority 0 ; s:identifier ?id ; s:name ?title ;
    seed:priority ?priority ; seed:status ?status ;
    s:version ?revision ; s:dateModified ?modified .
  OPTIONAL { ?item seed:rank ?rank }
  OPTIONAL { ?item s:agent ?owner }
  FILTER(?status = "open" || ?status = "in_progress")
  FILTER NOT EXISTS { ?item s:keywords "inbox" }
 }
} ORDER BY ?id LIMIT 21
